import java.util.Scanner;

public class P_B_Text_Document_Analysis {
	static int outMax, inMax, count = 0;

	public static void main(String[] args) {

		Scanner scanner = new Scanner(System.in);

		int stringLen = scanner.nextInt();

		String text = scanner.next();

		scanner.close();
		int i = 0;

		try {
			while (true) {

				if (text.charAt(i) == '(') {
					while (true) {
						int c=0;
							while (text.charAt(i) != '_' && text.charAt(i)!=')' && text.charAt(i)!='(') {
								if (c==0) {
									inMax++;
									c++;
								}
								i++;
							}


						if (text.charAt(i)==')') {
							count=0;
							break;

						}
						count=0;
						i++;
					}
				} else {
					while (true) {

							while (text.charAt(i) != '_' && text.charAt(i)!=')' && text.charAt(i)!='(') {
								count++;
								i++;
							}



						if (outMax < count) {
							outMax = count;
							count = 0;
						}

						if (text.charAt(i)=='(') {
							count=0;
							break;
						}
						count=0;
						i++;
					}
				}
			}
		} catch (Exception e) {

		}finally{
			if (outMax < count) {
				outMax = count;
			}
		}

		System.out.print(outMax + " " + inMax);

	}

}

